type:
∀ {depth mesh : Nat} (P : ImbalancedChen.P2PhysicalIncomingPrefixCells.CapPlan depth mesh) (a b : Real)
  (X Y : ImbalancedChen.P2LowerCapPlanIntegerRetention.Trace),
  @Eq.{1} Bool X.accepted Bool.true →
    @Eq.{1} Bool Y.accepted Bool.true →
      ∀ (xs ys : List.{0} Real),
        @Eq.{1} Nat (@List.length.{0} Real xs) (@List.length.{0} Real ys) →
          Not
              (Iff
                (@Eq.{1} Bool (@ImbalancedChen.P2LowerCapPlanIntegerRetention.run depth mesh P a b X xs).accepted
                  Bool.true)
                (@Eq.{1} Bool (@ImbalancedChen.P2LowerCapPlanIntegerRetention.run depth mesh P a b Y ys).accepted
                  Bool.true)) →
            @ImbalancedChen.P3OriginalU5JointWarmWalls.FirstGateDifference depth mesh P a b X Y xs ys

∀ (xs : List.{0} Real) (k : Nat),
  @LT.lt.{0} Nat instLTNat k (@List.length.{0} Real xs) →
    ∀ (i : Nat),
      @LT.lt.{0} Nat instLTNat i k →
        @LT.lt.{0} Nat (@Preorder.toLT.{0} Nat Nat.instPreorder) i (@List.length.{0} Real xs)

∀ (xs ys : List.{0} Real),
  @Eq.{1} Nat (@List.length.{0} Real xs) (@List.length.{0} Real ys) →
    ∀ (k : Nat),
      @LT.lt.{0} Nat instLTNat k (@List.length.{0} Real ys) →
        Not (@LT.lt.{0} Nat instLTNat k (@List.length.{0} Real xs)) → False

∀ (xs ys : List.{0} Real),
  @Eq.{1} Nat (@List.length.{0} Real xs) (@List.length.{0} Real ys) →
    ∀ (k : Nat),
      @LT.lt.{0} Nat instLTNat k (@List.length.{0} Real xs) →
        Not (@LT.lt.{0} Nat instLTNat k (@List.length.{0} Real ys)) → False
